CREATE TABLE nota_app.upload_groups (id uuid PRIMARY KEY, uid text REFERENCES nota_app.profiles(uid), branch_id text REFERENCES nota_app.branches(id), expected_photos integer NOT NULL CHECK(expected_photos BETWEEN 1 AND 5), status text NOT NULL DEFAULT 'OCR_PROCESSING', created_at timestamptz NOT NULL DEFAULT now(), receipt_ids jsonb);
CREATE TABLE nota_app.ocr_photos (upload_id uuid REFERENCES nota_app.upload_groups(id), client_photo_id text, photo_id uuid REFERENCES nota_app.photos(id), job_id uuid REFERENCES nota_app.jobs(id), result jsonb, PRIMARY KEY(upload_id,client_photo_id));
